    {
      "@id": "entity:source-homeschool.feature_1_desc",
      "@type": "prov:Entity",
      "prov:value": "Build activities tied to real places — nature trails, museums, historical sites, or your own backyard. Each child follows guided prompts and captures evidence on their device."
